CREATE TABLE IF NOT EXISTS `iptv_apps` (
  `id`           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name`         VARCHAR(120) NOT NULL,
  `icon`         VARCHAR(10)  NOT NULL DEFAULT '📺',
  `category`     VARCHAR(60)  NOT NULL COMMENT 'smartphone | tv | pc | box',
  `is_free`      TINYINT(1)   NOT NULL DEFAULT 1,
  `price`        JSON         NULL     COMMENT '{"fr":"...","en":"...","es":"...","de":"..."}',
  `platforms`    JSON         NOT NULL COMMENT '["iOS","Android",...]',
  `device_types` JSON         NOT NULL COMMENT '["smartphone","tv","pc","box"]',
  `blog_slug`    VARCHAR(200) NULL,
  `descriptions` JSON         NOT NULL COMMENT '{"fr":"...","en":"...","es":"...","de":"..."}',
  `steps`        JSON         NOT NULL COMMENT '{"fr":["..."],"en":["..."],"es":["..."],"de":["..."]}',
  `status`       ENUM('active','inactive') NOT NULL DEFAULT 'active',
  `sort_order`   SMALLINT     NOT NULL DEFAULT 0,
  `created_at`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_category` (`category`),
  INDEX `idx_status`   (`status`),
  INDEX `idx_sort`     (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

