('GSE Smart IPTV','📱','smartphone',1,NULL,
 '["iOS","Android"]','["smartphone"]',
 'gse-smart-iptv-guide-complet',
 '{"fr":"L\'application mobile la plus populaire et complète avec support M3U et Xtream Codes.","en":"The most popular and comprehensive mobile app with M3U and Xtream Codes support.","es":"La aplicación móvil más popular y completa con soporte para M3U y Xtream Codes.","de":"Die beliebteste und umfassendste mobile App mit Unterstützung für M3U und Xtream Codes."}',
 '{"fr":["Téléchargez GSE Smart IPTV depuis l\'App Store ou Google Play Store.","Ouvrez le menu latéral gauche et cliquez sur \'Playlists distantes\'.","Cliquez sur le bouton \'+\' puis sur \'Ajouter URL M3U\'.","Entrez l\'URL M3U de votre abonnement RegardezIPTV et validez."],"en":["Download GSE Smart IPTV from the App Store or Play Store.","Open the left sidebar menu and click on \'Remote Playlists\'.","Click the \'+\' button and then \'Add M3U URL\'.","Enter your RegardezIPTV M3U URL and save."],"es":["Descargue GSE Smart IPTV desde la App Store o Play Store.","Abra el menú lateral izquierdo y haga clic en \'Listas de reproducción remotas\'.","Haga clic en el botón \'+\' y luego en \'Añadir URL M3U\'.","Introduzca la URL M3U de su suscripción de RegardezIPTV y guarde."],"de":["Laden Sie GSE Smart IPTV aus dem App Store oder Play Store herunter.","Öffnen Sie das linke Seitenmenü und klicken Sie auf \'Remote-Playlists\'.","Klicken Sie auf das \'+\'-Symbol und wählen Sie \'M3U-URL hinzufügen\'.","Geben Sie die M3U-URL Ihres RegardezIPTV-Abonnements ein und speichern Sie."]}',
 'active',1),

('IPTV Smarters Pro','⚡','smartphone',0,
 '{"fr":"Gratuit / Pro à 3,49€","en":"Free / Pro for €3.49","es":"Gratis / Pro por 3,49€","de":"Kostenlos / Pro für 3,49€"}',
 '["iOS","Android","Fire Stick"]','["smartphone","box"]',NULL,
 '{"fr":"Interface moderne avec gestion multi-playlists, guide des programmes (EPG) et VOD intégrée.","en":"Modern interface with multi-playlist management, TV Guide (EPG), and built-in VOD.","es":"Interfaz moderna con gestión de listas múltiples, guía de programación (EPG) y VOD integrado.","de":"Moderne Benutzeroberfläche mit Multi-Playlist-Verwaltung, EPG und integriertem VOD."}',
 '{"fr":["Installez l\'application depuis votre magasin d\'applications (ou Smarters Player Lite sur iOS).","Choisissez l\'option de connexion \'Xtream Codes API\'.","Entrez le nom de la playlist (ex: RegardezIPTV).","Saisissez votre nom d\'utilisateur, mot de passe et l\'URL du serveur reçus par email.","Cliquez sur \'Add User\' pour charger les chaînes."],"en":["Install the app from your official app store (or Smarters Player Lite on iOS).","Select the login option \'Xtream Codes API\'.","Enter a name for the playlist (e.g., RegardezIPTV).","Enter your username, password, and server URL received by email.","Click \'Add User\' to load the channels."],"es":["Instale la aplicación desde la tienda oficial (o Smarters Player Lite en iOS).","Seleccione la opción de inicio de sesión \'Xtream Codes API\'.","Introduzca un nombre para la lista (ej: RegardezIPTV).","Introduzca su usuario, contraseña y URL del servidor recibidos por email.","Haga clic en \'Add User\' para cargar los canales."],"de":["Installieren Sie die App aus Ihrem App Store (oder Smarters Player Lite unter iOS).","Wählen Sie die Anmeldeoption \'Xtream Codes API\'.","Geben Sie einen Namen für die Playlist ein (z. B. RegardezIPTV).","Geben Sie Ihren Benutzernamen, Ihr Passwort und die Server-URL aus Ihrer E-Mail ein.","Klicken Sie auf \'Add User\', um die Kanäle zu laden."]}',
 'active',2),

('Televizo','📱','smartphone',0,
 '{"fr":"Gratuit / Premium à 2,49€","en":"Free / Premium for €2.49","es":"Gratis / Premium por 2,49€","de":"Kostenlos / Premium für 2,49€"}',
 '["Android TV","Fire Stick","Android"]','["smartphone","box"]',NULL,
 '{"fr":"Lecteur moderne très propre, avec sous-titres, audio multi-pistes, EPG et zapping réactif.","en":"Very clean modern player with subtitles, multi-track audio, EPG, and responsive channel switching.","es":"Reproductor moderno muy limpio, con subtítulos, audio multipista, EPG y cambio rápido de canales.","de":"Sehr sauberer, moderner Player mit Untertiteln, Multi-Audio-Tracks, EPG und schnellem Umschalten."}',
 '{"fr":["Téléchargez Televizo depuis le Google Play Store ou Downloader.","Ouvrez l\'application et cliquez sur \'Ajouter une playlist\'.","Sélectionnez \'Playlist M3U\' ou \'Xtream Codes\'.","Renseignez vos coordonnées IPTV et sauvegardez pour charger."],"en":["Download Televizo from the Google Play Store or via Downloader.","Open the app and click on \'Add playlist\'.","Select \'M3U Playlist\' or \'Xtream Codes\'.","Enter your IPTV details and click save to load the channels."],"es":["Descargue Televizo desde Google Play Store o mediante Downloader.","Abra la aplicación y haga clic en \'Añadir lista\'.","Seleccione \'Lista M3U\' o \'Xtream Codes\'.","Introduzca sus datos de IPTV y pulse guardar para cargar."],"de":["Laden Sie Televizo aus dem Google Play Store oder über Downloader herunter.","Öffnen Sie die App und klicken Sie auf \'Playlist hinzufügen\'.","Wählen Sie \'M3U-Playlist\' oder \'Xtream Codes\'.","Geben Sie Ihre IPTV-Daten ein und speichern Sie."]}',
 'active',3),

