('SS IPTV','🌐','tv',1,NULL,
 '["Samsung","LG","Android TV"]','["tv"]',
 'configurer-code-iptv-ss-iptv',
 '{"fr":"Application entièrement gratuite pour TV connectées supportant le zapping direct et le chargement à distance.","en":"Completely free application for connected Smart TVs supporting instant zapping and remote playlist loading.","es":"Aplicación totalmente gratuita para Smart TV con soporte para cambio rápido de canal y carga remota de listas.","de":"Völlig kostenlose App für Smart TVs mit Unterstützung für schnelles Zappen und Remote-Playlists."}',
 '{"fr":["Recherchez et installez SS IPTV sur le Content Store LG ou Samsung App Store.","Ouvrez l\'application, allez dans Paramètres (engrenage), et cliquez sur \'Obtenir le code de connexion\'.","Rendez-vous sur le site officiel ss-iptv.com dans la section éditeur de playlist.","Entrez le code pour lier votre TV, ajoutez une playlist externe et insérez votre URL M3U."],"en":["Search and install SS IPTV from the LG Content Store or Samsung App Store.","Open the app, go to Settings, and click \'Get connection code\'.","Visit the official website ss-iptv.com and go to the playlist editor section.","Enter the code to link your TV, add an external playlist, and paste your M3U URL."],"es":["Busque e instale SS IPTV en LG Content Store o Samsung App Store.","Abra la aplicación, vaya a Ajustes y haga clic en \'Obtener código de conexión\'.","Vaya al sitio web oficial ss-iptv.com en la sección de editor de listas.","Introduzca el código para vincular su TV, añada una lista externa e inserte su URL M3U."],"de":["Suchen und installieren Sie SS IPTV auf Ihrem LG oder Samsung Smart TV.","Öffnen Sie die App, gehen Sie in die Einstellungen und klicken Sie auf \'Verbindungscode abrufen\'.","Besuchen Sie die offizielle Website ss-iptv.com im Bereich Playlist-Editor.","Geben Sie den Code ein, um Ihren TV zu koppeln, fügen Sie eine externe Playlist hinzu und tragen Sie Ihre M3U-URL ein."]}',
 'active',6),

('Net IPTV','🌐','tv',0,
