('VLC Media Player','🔶','pc',1,NULL,
 '["Windows","Mac","Linux"]','["pc"]',NULL,
 '{"fr":"Le lecteur média universel open-source, parfait pour tester ou regarder l\'IPTV sur ordinateur.","en":"The universal open-source media player, perfect for testing or watching IPTV on computers.","es":"El reproductor de medios universal de código abierto, perfecto para probar o ver IPTV en el ordenador.","de":"Der universelle Open-Source-Mediaplayer, perfekt zum Testen oder Anschauen von IPTV auf dem PC."}',
 '{"fr":["Téléchargez et installez VLC Media Player depuis le site officiel de VideoLAN.","Ouvrez VLC, allez dans Média > Ouvrir un flux réseau (Ctrl+N).","Collez l\'URL M3U de votre abonnement dans le champ d\'adresse.","Cliquez sur \'Lire\'. Affichez la liste de lecture (Ctrl+L) pour naviguer entre les chaînes."],"en":["Download and install VLC Media Player from the official VideoLAN website.","Open VLC, navigate to Media > Open Network Stream (Ctrl+N).","Paste your subscription M3U URL into the address field.","Click \'Play\'. Toggle the playlist view (Ctrl+L) to navigate through channels."],"es":["Descargue e instale VLC Media Player desde el sitio web oficial de VideoLAN.","Abra VLC, vaya a Medio > Abrir volcado de red (Ctrl+N).","Pegue la URL M3U de su suscripción en el campo de dirección.","Haga clic en \'Reproducir\'. Active la lista de reproducción (Ctrl+L) para navegar por los canales."],"de":["Laden Sie VLC Media Player von der offiziellen VideoLAN-Website herunter und installieren Sie ihn.","Öffnen VLC, gehen Sie auf Medien > Netzwerkstream öffnen (Strg+N).","Fügen Sie Ihre M3U-URL in das Adressfeld ein.","Klicken Sie auf \'Wiedergabe\'. Drücken Sie Strg+L, um die Playlist anzuzeigen und Kanäle auszuwählen."]}',
 'active',15),

('MyIPTV Player','💻','pc',1,NULL,
 '["Windows"]','["pc"]',NULL,
 '{"fr":"Application Windows native disponible sur le Microsoft Store, avec un bon support EPG et filtres.","en":"Native Windows application available on the Microsoft Store, featuring solid EPG support and channel filters.","es":"Aplicación nativa de Windows disponible en Microsoft Store, con buen soporte de EPG y filtros de canales.","de":"Native Windows-App aus dem Microsoft Store mit gutem EPG-Support und Kanalsortierung."}',
 '{"fr":["Installez MyIPTV Player depuis le Microsoft Store de Windows 10/11.","Allez dans Settings > Add new playlist and EPG source.","Collez votre URL M3U de RegardezIPTV dans la section \'Remote channel list\'.","Nommez-la, cliquez sur \'Add list\', puis sélectionnez-la dans la page des paramètres généraux et cliquez sur \'Refresh\'."],"en":["Install MyIPTV Player from the Microsoft Store on Windows 10/11.","Go to Settings > Add new playlist and EPG source.","Paste your RegardezIPTV M3U URL under the \'Remote channel list\' section.","Name the list, click \'Add list\', go back to general settings, select it, and click \'Refresh\'."],"es":["Instale MyIPTV Player desde Microsoft Store en Windows 10/11.","Vaya a Ajustes > Añadir nueva lista y fuente EPG.","Pegue su URL M3U de RegardezIPTV en la sección \'Remote channel list\'.","Asigne un nombre, haga clic en \'Add list\', regrese a ajustes generales, selecciónela y haga clic en \'Refresh\'."],"de":["Installieren Sie MyIPTV Player aus dem Microsoft Store unter Windows 10/11.","Gehen Sie zu Einstellungen > Neue Playlist und EPG-Quelle hinzufügen.","Fügen Sie Ihre RegardezIPTV M3U-URL unter \'Remote-Kanalliste\' ein.","Geben Sie einen Namen ein, klicken Sie auf \'Add list\', wählen Sie sie in den Haupteinstellungen aus und klicken Sie auf \'Refresh\'."]}',
 'active',16),

